// Park sensörü: HC-SR04 mesafeyi ölçer, buzzer yakınlığa göre öter.
const int TRIG_PIN = 9;
const int ECHO_PIN = 10;
const int BUZZER_PIN = 8;

void setup() {
  Serial.begin(9600);
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  pinMode(BUZZER_PIN, OUTPUT);
}

// Mesafeyi cm olarak döndürür; ölçüm yoksa -1.
long mesafeOlc() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);
  long sure = pulseIn(ECHO_PIN, HIGH, 30000);
  if (sure == 0) return -1;
  return sure / 58;
}

void loop() {
  long cm = mesafeOlc();
  Serial.print("Mesafe: ");
  Serial.print(cm);
  Serial.println(" cm");

  if (cm > 0 && cm < 10) {
    tone(BUZZER_PIN, 1000);
    delay(100);
  } else if (cm > 0 && cm < 50) {
    noTone(BUZZER_PIN);
    tone(BUZZER_PIN, 1000, 80);
    delay(80 + cm * 8);
  } else {
    noTone(BUZZER_PIN);
    delay(200);
  }
}
